"""Subtraction on a number line: from the first number, hop back by the hundreds, the
tens and the ones of the second, landing on the difference; or (Count up) hop from the
smaller number up to the larger one and add up the hops. Drawn in the picture's Paint
event, in the picture's own scale: the line runs over the numbers involved.

Counting up finds the same difference another way: the hops from 275 up to 532 add up
to how far apart they are, 532 − 275."""

import math

from vp6 import *


def hops_back(a, b):
    """The hops from a down to a - b: b's hundreds, tens and ones, as (from, to)."""
    hops, at = [], a
    for step in (100, 10, 1):
        size = b // step % 10 * step if step < 100 else b // 100 * 100
        if size:
            hops.append((at, at - size))
            at -= size
    return hops


def hops_up(low, high):
    """From low up to high: to the next ten, the next hundred, then on to high."""
    hops, at = [], low
    for step in (10, 100):
        nearer = -(-at // step) * step  # (the next multiple of step)
        if at < nearer <= high:
            hops.append((at, nearer))
            at = nearer
    for step in (1000, 100, 10, 1):
        while at + step <= high:
            size = (high - at) // step * step
            hops.append((at, at + size))
            at += size
    return hops


class Form1(Form):
    # region VP6 Designer - generated by the form designer, do not edit
    def InitializeComponent(self):
        self.Caption = 'Subtraction on a Number Line'
        self.Width = 680
        self.Height = 400
        self.lblA = Label(self, Caption='From:', Left=16, Top=18, Width=60, Height=24, TabIndex=1)
        self.txtA = TextBox(self, Text='532', Left=80, Top=14, Width=110, Height=28, TabIndex=2)
        self.lblB = Label(self, Caption='take away:', Left=206, Top=18, Width=80, Height=24,
                          TabIndex=3)
        self.txtB = TextBox(self, Text='275', Left=290, Top=14, Width=110, Height=28, TabIndex=4)
        self.chkUp = CheckBox(self, Caption='&Count up', Left=420, Top=16, Width=140, Height=26,
                              TabIndex=5,
                              ToolTipText='Find the difference by hopping up from the smaller number')
        self.picLine = PictureBox(self, Left=16, Top=56, Width=640, Height=220, BackColor=0xFAFFFF,
                                  TabIndex=6)
        self.lblResult = Label(self, Caption='', Left=16, Top=288, Width=640, Height=60,
                               WordWrap=True, FontSize=14, TabIndex=7)
    # endregion

    def Form_Load(self):
        self.show()

    def txtA_Change(self):
        self.show()

    def txtB_Change(self):
        self.show()

    def chkUp_Click(self):
        self.show()

    def numbers(self):
        a, b = self.txtA.Text.replace(",", "").strip(), self.txtB.Text.replace(",", "").strip()
        if a.isdigit() and b.isdigit() and int(b) <= int(a):
            return int(a), int(b)
        return None

    def hops(self):
        a, b = self.numbers()
        return hops_up(b, a) if self.chkUp.Value else hops_back(a, b)

    def show(self):
        found = self.numbers()
        if found is None:
            self.lblResult.Caption = "Type two whole numbers, the second no larger than the first."
        else:
            a, b = found
            sizes = [abs(end - start) for start, end in self.hops()]
            if self.chkUp.Value:  # (the hops add up to the difference)
                self.lblResult.Caption = (f"From {b:,} up to {a:,}: hops of "
                                          f"{' + '.join(f'{s:,}' for s in sizes) or '0'} = "
                                          f"{sum(sizes):,}, the difference.")
            else:
                self.lblResult.Caption = (f"{a:,} − {b:,}: hop back "
                                          f"{', '.join(f'{s:,}' for s in sizes) or 'nothing'} "
                                          f"and land on {a - b:,}.")
        self.picLine.Refresh()

    def picLine_Paint(self):
        found = self.numbers()
        if found is None:
            return
        a, b = found
        pic = self.picLine
        low, high = (b if self.chkUp.Value else a - b), a
        span = max(high - low, 1)
        margin = span * 0.08 + 1
        pic.Scale(low - margin, 0, high + margin, 220)  # (X in numbers, Y in pixels)
        ink = RGB(40, 40, 40)
        pic.DrawWidth = 2
        pic.Line(low - margin, 160, high + margin, 160, ink)
        pic.DrawWidth = 1
        pic.FontSize = 9
        for value in (low, high):
            pic.Line(value, 152, value, 168, ink)
            pic.ForeColor = ink
            pic.DrawText(f"{value:,}", value - span * 0.1, 172, value + span * 0.1, 192)
        colors = (RGB(220, 80, 50), RGB(40, 120, 210), RGB(40, 160, 80), RGB(150, 80, 200))
        for i, (start, end) in enumerate(self.hops()):
            color = colors[i % len(colors)]
            middle, width = (start + end) / 2, abs(end - start)
            height = 30 + 80 * width / span
            pic.CurrentX, pic.CurrentY = start, 160
            for k in range(1, 25):  # (a half ellipse from start to end, in 24 pieces)
                angle = math.pi * k / 24
                pic.Line(middle - (middle - start) * math.cos(angle),
                         160 - height * math.sin(angle), Color=color)
            pic.Line(end, 156, end, 164, color)
            pic.ForeColor = color
            sign = "+" if end > start else "−"
            pic.DrawText(f"{sign}{width:,}", middle - span * 0.1, 140 - height,
                         middle + span * 0.1, 158 - height)


if __name__ == "__main__":
    run(Form1)
